  scenery = {
    ["Auberdine"] = { type = "town", faction = "alliance", home = {  },
      { "Auberdine: a small harbour on a grey shore, its piers busy with boats to Teldrassil and beyond, its people tired and watchful.", tags = { "!foe" } },
      { "Auberdine, the Alliance's harbour on Darkshore. I watched the ships and kept moving.", tags = { "foe" } },
    },
    ["Blackfathom Deeps"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Blackfathom Deeps: an old night elf temple sunk into the sea, its halls full of black water, naga and cultists. Something ancient waits at the bottom. It isn't sleeping." },
    },
    ["Brill"] = { type = "town", faction = "horde", home = { ["Scourge"] = true },
      { "Brill: crooked houses, the Gallows' End Tavern, apothecaries brewing things best not smelled. A town of the dead, and as lively as we get.", tags = { "home" } },
      { "Brill, a village of the Forsaken: crooked roofs, a tavern called the Gallows' End, and townsfolk who were all, technically, dead.", tags = { "!home" } },
    },
    ["Darkshore"] = { type = "zone", faction = "alliance", home = {  },
      { "Darkshore: a long grey coast, mist rolling in from the sea, old elven ruins sinking into the sand. Even the forest seemed tired here.", tags = { "!night" } },
      { "Darkshore at night: the sea black, the mist thick, and the moon a pale smear behind it. Quiet, and not the restful kind.", tags = { "night" } },
    },
    ["Darnassus"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "Darnassus, high in the branches of Teldrassil: white stone, still water, and the Temple of the Moon where Tyrande keeps Elune's light. I walked slowly, as one should.", tags = { "home" } },
      { "Darnassus, the night elves' city in the World Tree's crown: pale stone, quiet pools, and a stillness that made me lower my voice.", tags = { "ally" } },
      { "Darnassus, the night elves' city. Quiet as a held breath, and just as tense.", tags = { "foe" } },
    },
    ["Dolanaar"] = { type = "town", faction = "alliance", home = { ["NightElf"] = true },
      { "Dolanaar: a few elegant houses of wood and vine around a moonwell, sentinels at the road, and the smell of rain. A small place, and a peaceful one.", tags = { "home" } },
      { "Dolanaar, a night elf village of graceful houses and a moonwell that glowed faintly blue. Everyone spoke quietly.", tags = { "!home" } },
    },
    ["Dun Morogh"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "Dun Morogh: snow to the knee, pines bent under it, and the mountain that holds Ironforge standing over everything like a grandfather. The air bites, and I breathed it in like ale. Home.", tags = { "home", "!night" } },
      { "Dun Morogh by night, the snow blue under the stars and the lamps of the villages small and warm. I knew every shape of the mountains against the sky.", tags = { "home", "night" } },
      { "Dun Morogh, the dwarves' country: deep snow, hard rock, and the gate of Ironforge cut into the mountain itself. Everyone I met had a pipe, an opinion, or both.", tags = { "ally" } },
      { "Dun Morogh, deep in the dwarves' land. Snow, cold, and a mountain full of their warriors. I kept off the roads.", tags = { "foe" } },
    },
    ["Durotar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Durotar: red rock, red dust, a sun that hammers the ground. A hard land, named for Thrall's father. We made it ours anyway.", tags = { "home", "!night" } },
      { "Durotar at night: the red earth gone grey, the heat leaving the stones, the drums of Orgrimmar carried far on the wind.", tags = { "home", "night" } },
      { "Durotar, the orcs' red country: dry hills, scorpids under every rock, and the great gate of Orgrimmar standing in the canyon. Harsh, and proud of it.", tags = { "ally" } },
      { "Durotar, the heart of the Horde: red rock, hot wind, and orcs on every ridge. I kept my head down.", tags = { "foe" } },
    },
    ["Gnomeregan"] = { type = "dungeon", faction = "alliance", home = { ["Gnome"] = true },
      { "Gnomeregan. The city of my people, now full of troggs, poison and the friends we left behind, gone mad from the radiation. I had imagined coming back many times. Never like this.", tags = { "home" } },
      { "Gnomeregan, the gnomes' lost city: endless metal halls, clanking machines still running with no one to run them, and a green glow I did not trust. Something here had gone very wrong.", tags = { "!home" } },
    },
    ["Ironforge"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true },
      { "Ironforge. The heat of the Great Forge on my face, the ring of a thousand hammers, molten iron running in channels under the bridges. My father's city, and his father's. I stood still a moment, and let it fill me.", tags = { "home" } },
      { "Ironforge, carved into the heart of the mountain: the Great Forge glowing at its centre, hammers ringing in every hall, and dwarves everywhere, loud, busy and proud of it.", tags = { "ally" } },
      { "Ironforge, the dwarves' fortress under the mountain. Every hall full of hammers and guards. I did not linger.", tags = { "foe" } },
    },
    ["Kharanos"] = { type = "town", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "Kharanos: smoke from every chimney, the smell of the Thunderbrew Distillery on the wind, and gnome refugees from Gnomeregan huddled among the dwarven houses. Warm, loud, and ours.", tags = { "home" } },
      { "Kharanos, a dwarven village in the snow: stout stone houses, a distillery you could smell from the road, and a good many gnomes, homeless since Gnomeregan fell.", tags = { "ally" } },
      { "Kharanos, a dwarven village. Smoke, ale, and too many of them for comfort.", tags = { "foe" } },
    },
    ["Loch Modan"] = { type = "zone", faction = "alliance", home = {  },
      { "Loch Modan opened below me: red hills, a long blue loch, and at its head the Stonewrought Dam, holding back more water than I could imagine. Troggs and Dark Irons in the hills, they said. They were right.", tags = { "!night" } },
      { "Loch Modan at night: the loch black and still, the dam a dark wall at its head, and the lights of Thelsamar small on the shore.", tags = { "night" } },
      { "Loch Modan, the dwarves' lake country, with their great dam at its head. Their guards watched the roads. I watched them.", tags = { "foe" } },
    },
    ["Orgrimmar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Orgrimmar: walls of red stone and iron spikes, the drums never quite silent, Grommash Hold where the Warchief sits. Built by Thrall, named for Orgrim Doomhammer. The city of the Horde, and of me.", tags = { "home" } },
      { "Orgrimmar, the orcs' capital, cut into a canyon of red rock: spiked walls, smoke, drums, and a pride you could feel in the street.", tags = { "ally" } },
      { "Orgrimmar. Spikes, walls, and the whole Horde inside them. No place for me.", tags = { "foe" } },
    },
    ["Ragefire Chasm"] = { type = "dungeon", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Ragefire Chasm, beneath Orgrimmar itself: rivers of fire, choking heat, and traitors of the Burning Blade hiding in it. In the belly of our own city. Shameful.", tags = { "home" } },
      { "Ragefire Chasm, a cave of fire under Orgrimmar: magma, troggs, and cultists who should not be there.", tags = { "!home" } },
    },
    ["Razor Hill"] = { type = "town", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Razor Hill: a barracks, a forge and orcs drilling in the dust, the sea close by and Kul Tiras ships watching from it. A soldiers' town.", tags = { "home" } },
      { "Razor Hill, an orcish town of barracks and watchtowers on the road to the coast. Everyone there carried a weapon, and looked ready to use it.", tags = { "!home" } },
    },
    ["Shadowfang Keep"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Shadowfang Keep, high above Pyrewood: Arugal's keep, full of his worgen and the ghosts of its old masters. Cold stone, howling halls, and the madness that started all of it." },
    },
    ["Silverpine Forest"] = { type = "zone", faction = "horde", home = {  },
      { "Silverpine Forest: dark pines, cold rain, a grey lake, and the purple dome over Dalaran on the far shore. Worgen howl in the hills. Nobody here sleeps well.", tags = { "!night" } },
      { "Silverpine at night: the howls closer, the pines black, the rain never stopping.", tags = { "night" } },
    },
    ["Teldrassil"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "Teldrassil, the World Tree: a whole land grown on its branches, soft light through leaves taller than towers, wisps drifting over the moss. Home, and still new to us.", tags = { "home", "!night" } },
      { "Teldrassil by night: the moonlight silver on every leaf, the owls calling, the whole tree breathing slowly in its sleep.", tags = { "home", "night" } },
      { "Teldrassil, the night elves' tree, so vast a forest grows on its boughs. Soft violet light, quiet paths, and sentinels watching from the shadows.", tags = { "ally" } },
      { "Teldrassil, the night elves' tree. Beautiful, silent, and full of eyes I could not see.", tags = { "foe" } },
    },
    ["The Barrens"] = { type = "zone", faction = "horde", home = {  },
      { "The Barrens: yellow grass to the edge of the world, a few thorny trees, zhevra running in herds, and a heat that never lets go. Quilboar and centaur claim it; so does the Horde.", tags = { "!night" } },
      { "The Barrens by night: the grass silver, the sky enormous, and somewhere out there the drums of the centaur.", tags = { "night" } },
    },
    ["The Crossroads"] = { type = "town", faction = "horde", home = {  },
      { "The Crossroads: a Horde fort where the roads of the Barrens meet, its palisade the only shade for miles. Everyone passes through it sooner or later.", tags = { "!foe" } },
      { "The Crossroads, the Horde's fort at the heart of the Barrens. I gave it a wide berth.", tags = { "foe" } },
    },
    ["The Sepulcher"] = { type = "town", faction = "horde", home = { ["Scourge"] = true },
      { "The Sepulcher: a Forsaken outpost dug into a hill of tombs. Bats overhead, dead guards at the gate. Cosy.", tags = { "home" } },
      { "The Sepulcher, a Forsaken outpost built among tombs. The guards did not blink. I don't think they could.", tags = { "!home" } },
    },
    ["Thelsamar"] = { type = "town", faction = "alliance", home = {  },
      { "Thelsamar sits by the loch, a handful of houses and the Stoutlager Inn, where the blood sausages are the pride of the town and the ale is the pride of everyone else.", tags = { "!foe" } },
      { "Thelsamar, a lakeside village of the Alliance. I kept to the edges of it.", tags = { "foe" } },
    },
    ["Tirisfal Glades"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "Tirisfal Glades: grey grass, dead trees, a sky that never quite clears. The plague left it like this; we live in what remained. I find it restful.", tags = { "home", "!night" } },
      { "Tirisfal at night, which is to say much like Tirisfal by day, only honest about it. The crypts, the crows, the ruins of Lordaeron on the horizon.", tags = { "home", "night" } },
      { "Tirisfal Glades, the Forsaken's land: grey fields, dead trees, crows, and the broken walls of Lordaeron. A sad country, and its people are sadder.", tags = { "ally" } },
      { "Tirisfal Glades, where the Forsaken walk. Dead trees, grey sky, and a smell I would rather forget.", tags = { "foe" } },
    },
    ["Undercity"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "The Undercity, beneath the ruins of Lordaeron: green slime in the canals, the Apothecarium bubbling, and the Dark Lady in her Royal Quarter. The living built it as a crypt. We made it a city.", tags = { "home" } },
      { "The Undercity, the Forsaken's capital beneath ruined Lordaeron: green sludge in stone canals, endless sewers, and a smell nothing gets used to.", tags = { "ally" } },
      { "The Undercity, beneath the ruins of Lordaeron. The Forsaken's home, and no place for the living.", tags = { "foe" } },
    },
    ["Wailing Caverns"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Wailing Caverns: green water, twisted roots, and a moaning wind in the stone that never stops. Druids went in to heal this land and came out wrong. The creatures down there are worse." },
    },
  },
}
